import{az as a,P as n,Q as l,aQ as o}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"css/新特性/layer.md","filePath":"css/新特性/layer.md","lastUpdated":1785249401000}'),p={name:"css/新特性/layer.md"};function e(t,s,c,r,i,D){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h2 id="层叠层-layer" tabindex="-1">层叠层（@layer） <a class="header-anchor" href="#层叠层-layer" aria-label="Permalink to “层叠层（@layer）”">​</a></h2><blockquote><p>MDN 参考：<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/@layer" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/CSS/@layer</a></p></blockquote><p>层叠层（Cascade Layers）是 CSS 层叠算法的重大改进。它允许开发者将样式规则分组到命名的&quot;层&quot;中，并显式控制这些层之间的优先级顺序，从而优雅地解决 CSS 优先级战争。</p><h3 id="一、为什么需要层叠层" tabindex="-1">一、为什么需要层叠层 <a class="header-anchor" href="#一、为什么需要层叠层" aria-label="Permalink to “一、为什么需要层叠层”">​</a></h3><p>在传统 CSS 中，样式的优先级由选择器特异性（specificity）和书写顺序决定。当引入第三方库（如 Tailwind、Bootstrap、Element UI）时，经常出现以下问题：</p><ul><li>想覆盖第三方样式，只能靠提升选择器特异性或使用 <code>!important</code>，导致代码混乱。</li><li>自己的样式与库的样式互相覆盖，难以预测最终结果。</li></ul><p>层叠层把&quot;谁优先&quot;这件事从&quot;特异性 + 顺序&quot;变成了&quot;显式声明的层级&quot;。同一层内才比较特异性和顺序，层与层之间按声明顺序确定优先级。</p><h3 id="二、-layer-基本语法" tabindex="-1">二、@layer 基本语法 <a class="header-anchor" href="#二、-layer-基本语法" aria-label="Permalink to “二、@layer 基本语法”">​</a></h3><p>声明层并定义顺序：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> reset, base, components, utilities</span><span style="color:#89DDFF;">;</span></span></code></pre></div><p>上面一行声明了四个层，<strong>先声明的层优先级更低</strong>，后声明的层优先级更高。也就是说 <code>utilities</code> 优先级最高，<code>reset</code> 最低。</p><p>在层内书写规则：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> base </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#FFCB6B;">  h1</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 2rem</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#FFCB6B;">  p</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> line-height</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1.6</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> components </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">btn</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">    padding</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8px</span><span style="color:#F78C6C;"> 16px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">    background</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">3b82f6</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="三、命名层与匿名层" tabindex="-1">三、命名层与匿名层 <a class="header-anchor" href="#三、命名层与匿名层" aria-label="Permalink to “三、命名层与匿名层”">​</a></h3><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">/* 命名层 */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> theme </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  :</span><span style="color:#C792EA;">root</span><span style="color:#89DDFF;"> {</span><span style="color:#BABED8;"> --primary</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">3b82f6</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* 匿名层（不命名，但仍独立成一个层） */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">temp</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> color</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>匿名层的优先级高于所有命名层，但通常不推荐使用，会破坏可维护性。</p><h3 id="四、层叠顺序规则" tabindex="-1">四、层叠顺序规则 <a class="header-anchor" href="#四、层叠顺序规则" aria-label="Permalink to “四、层叠顺序规则”">​</a></h3><p>完整的优先级从低到高为：</p><ol><li>用户代理样式（未分层）</li><li>用户代理层（<code>@layer</code> 内）</li><li>用户层</li><li>作者未分层样式（<strong>优先级高于所有层</strong>）</li><li>作者层（按声明顺序）</li><li><code>!important</code> 反转：分层 <code>!important</code> 优先级低于未分层 <code>!important</code></li></ol><p>关键点：<strong>未分层的样式优先级高于所有层内的样式</strong>。这意味着把第三方库放进层里，自己的未分层样式天然能覆盖它。</p><h3 id="五、-import-与-layer-配合" tabindex="-1">五、@import 与 layer 配合 <a class="header-anchor" href="#五、-import-与-layer-配合" aria-label="Permalink to “五、@import 与 layer 配合”">​</a></h3><p>这是层叠层最常见的用法之一：将第三方库的样式导入到一个低优先级层中。</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@import</span><span style="color:#82AAFF;"> url</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">reset.css</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span><span style="color:#BABED8;"> layer</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;">reset</span><span style="color:#89DDFF;">);</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@import</span><span style="color:#82AAFF;"> url</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">bootstrap.css</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span><span style="color:#BABED8;"> layer</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;">vendor</span><span style="color:#89DDFF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> reset, vendor, base, components</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> components </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">btn</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    /* 轻松覆盖 Bootstrap，无需提升特异性 */</span></span>
<span class="line"><span style="color:#B2CCD6;">    background</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">ef4444</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="六、实际应用-第三方库样式分层" tabindex="-1">六、实际应用：第三方库样式分层 <a class="header-anchor" href="#六、实际应用-第三方库样式分层" aria-label="Permalink to “六、实际应用：第三方库样式分层”">​</a></h3><p>假设项目中同时使用了 Tailwind 和自定义组件样式：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> tailwind-base, tailwind-utilities, components, overrides</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@import</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">tailwindcss/base</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;"> layer</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;">tailwind-base</span><span style="color:#89DDFF;">);</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@import</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">tailwindcss/utilities</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;"> layer</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;">tailwind-utilities</span><span style="color:#89DDFF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> components </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">my-button</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    /* 优先级高于 tailwind-base，低于 overrides */</span></span>
<span class="line"><span style="color:#B2CCD6;">    border-radius</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> overrides </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">my-button</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">important</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    /* 最高优先级，用于强制覆盖 */</span></span>
<span class="line"><span style="color:#B2CCD6;">    background</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">dc2626 </span><span style="color:#F78C6C;">!important</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="七、嵌套层" tabindex="-1">七、嵌套层 <a class="header-anchor" href="#七、嵌套层" aria-label="Permalink to “七、嵌套层”">​</a></h3><p>层还可以嵌套，用点号表示层级关系：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> framework </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  @layer</span><span style="color:#BABED8;"> base </span><span style="color:#89DDFF;">{</span><span style="color:#676E95;font-style:italic;"> /* framework.base */</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  @layer</span><span style="color:#BABED8;"> theme </span><span style="color:#89DDFF;">{</span><span style="color:#676E95;font-style:italic;"> /* framework.theme */</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* 引用嵌套层 */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@layer</span><span style="color:#BABED8;"> framework.base </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#FFCB6B;">  body</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> margin</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>嵌套层的优先级规则与顶层一致，按声明顺序，同层内才比较特异性。</p><h3 id="八、浏览器兼容性" tabindex="-1">八、浏览器兼容性 <a class="header-anchor" href="#八、浏览器兼容性" aria-label="Permalink to “八、浏览器兼容性”">​</a></h3><p>层叠层已被主流浏览器广泛支持：</p><ul><li>Chrome / Edge：99+（2022 年 3 月）</li><li>Safari：15.4+（2022 年 3 月）</li><li>Firefox：97+（2022 年 2 月）</li></ul><p>对于不支持的浏览器，<code>@layer</code> 内的规则会被忽略，可能导致样式缺失。建议在确认目标浏览器支持后再全面采用，或配合 <code>@supports</code> 做特性检测。</p>`,34)])])}const B=a(p,[["render",e]]);export{d as __pageData,B as default};
